function shareT(lang=language){return SHARE_LOCALES[lang]||SHARE_LOCALES['en-GB']}
function shareStoryLanguage(){return currentBook?.child?.language||language||'en-GB'}
function shareTokenFromLocation(){const m=location.pathname.match(/^\/shared\/([^/]+)\/?$/);return m?decodeURIComponent(m[1]):''}
async function loadSharedStory(token){
 try{
  const r=await fetch(`/api/share?action=story&token=${encodeURIComponent(token)}`,{cache:'no-store'}),data=await r.json();if(!r.ok)throw new Error(data?.error||shareT().sharedUnavailable);
  language=(data.language&&locales[data.language])?data.language:language;localStorage.setItem('moonbeamLanguage',language);applyLocale();const lang=$('language');if(lang)lang.value=language;
  // V127: shared links are an exclusive reader startup path. The story lives inside
  // #productApp, so that container must be visible; product-active also prevents the
  // mobile landing CSS from forcing #landing back on-screen with !important.
  $('landing')?.classList.add('hidden');$('productApp')?.classList.remove('hidden');document.body.classList.add('product-active');
  renderStory(data.story,null,{...(data.child||{}),language},{isSaved:true,isShared:true,shareToken:token,shareSenderName:data.senderName||'',visualCacheId:`shared:${token}`,savedAssets:data.savedAssets||{}});
  const head=document.querySelector('.book-cover-head');if(head)head.innerHTML=`<span>☾ Moonbeam Stories</span><span>${escapeHtml(shareT().sentBy(data.senderName||'Moonbeam'))}</span>`;
  // V128: reveal only after the shared reader has rendered. This removes the landing-page flash.
  document.documentElement.classList.remove('shared-link-boot');$('sharedBoot')?.remove();
 }catch(e){const sx=shareT();document.documentElement.classList.remove('shared-link-boot');document.body.classList.add('shared-story-error');document.body.innerHTML=`<main class="shared-error-card"><div class="logo">☾</div><h1>Moonbeam Stories</h1><h2>${escapeHtml(sx.unavailable)}</h2><p>${escapeHtml(e.message||String(e))}</p><a class="primary" href="/?lang=${encodeURIComponent(language)}">${escapeHtml(sx.visit)}</a></main>`}
}
function ensureShareDialog(){
 let d=$('shareStoryDialog');if(!d){d=document.createElement('div');d.id='shareStoryDialog';d.className='share-dialog hidden';d.innerHTML=`<div class="share-card" role="dialog" aria-modal="true" aria-labelledby="shareTitle"><button class="share-close" type="button">×</button><div class="share-kicker"></div><h2 id="shareTitle"></h2><p class="share-intro"></p><label class="share-sender-label"><span></span><input id="shareSenderName" maxlength="80" autocomplete="name"></label><div class="share-methods"><button class="share-method share-whatsapp" type="button">WhatsApp</button><button class="share-method share-email-method" type="button">Email</button></div><button class="secondary share-copy-link" type="button"></button><div id="shareEmailPanel" class="hidden"><div id="shareRecipients"></div><button class="secondary share-add" type="button"></button><button class="primary share-send" type="button"></button><button class="share-back" type="button"></button></div><div id="shareStatus" class="share-status"></div><div id="existingShares" class="existing-shares"></div></div>`;document.body.appendChild(d);d.querySelector('.share-close').onclick=()=>d.classList.add('hidden');d.addEventListener('click',e=>{if(e.target===d)d.classList.add('hidden')});d.querySelector('.share-add').onclick=()=>addShareRecipient();d.querySelector('.share-send').onclick=sendStoryShares;d.querySelector('.share-email-method').onclick=()=>showEmailSharePanel(true);d.querySelector('.share-back').onclick=()=>showEmailSharePanel(false);d.querySelector('.share-whatsapp').onclick=()=>shareStoryByLink('whatsapp');d.querySelector('.share-copy-link').onclick=()=>shareStoryByLink('copy')}
 return d
}
function showEmailSharePanel(show){const d=$('shareStoryDialog');if(!d)return;d.querySelector('.share-methods').classList.toggle('hidden',show);d.querySelector('.share-copy-link').classList.toggle('hidden',show);$('shareEmailPanel').classList.toggle('hidden',!show);$('shareStatus').textContent=''}
function applyShareDialogLocale(d=$('shareStoryDialog')){if(!d)return;const sx=shareT(shareStoryLanguage());d.lang=shareStoryLanguage();d.querySelector('.share-close').setAttribute('aria-label',sx.remove);d.querySelector('.share-kicker').textContent=sx.kicker;d.querySelector('#shareTitle').textContent=sx.title;d.querySelector('.share-intro').textContent=sx.methodIntro||sx.intro;d.querySelector('.share-sender-label span').textContent=sx.yourName;d.querySelector('#shareSenderName').placeholder=sx.senderPh;d.querySelector('.share-whatsapp').textContent='WhatsApp';d.querySelector('.share-email-method').textContent=sx.emailMethod||'Email';d.querySelector('.share-copy-link').textContent='🔗 '+(sx.copyLink||'Copy story link');d.querySelector('.share-add').textContent=sx.add;d.querySelector('.share-send').textContent=sx.send;d.querySelector('.share-back').textContent='← '+(sx.back||'Back');d.querySelectorAll('.share-recipient').forEach(applyShareRecipientLocale)}
function applyShareRecipientLocale(row){const sx=shareT(shareStoryLanguage());const e=row.querySelector('.share-recipient-email'),b=row.querySelector('.share-remove');if(e)e.placeholder=sx.email;if(b)b.setAttribute('aria-label',sx.remove)}
function addShareRecipient(){const box=$('shareRecipients');if(!box||box.children.length>=10)return;const row=document.createElement('div');row.className='share-recipient';row.innerHTML=`<input class="share-recipient-email" type="email" autocomplete="email"><button class="share-remove" type="button">×</button>`;row.querySelector('.share-remove').onclick=()=>{if(box.children.length>1)row.remove()};box.appendChild(row);applyShareRecipientLocale(row)}
async function openShareStory(){const sx=shareT(shareStoryLanguage());if(!currentUser){alert(sx.signIn);return}const d=ensureShareDialog(),sender=$('shareSenderName');applyShareDialogLocale(d);sender.value=localStorage.getItem('moonbeamShareSenderName')||'';$('shareRecipients').innerHTML='';addShareRecipient();showEmailSharePanel(false);$('shareStatus').textContent=currentBook?.isSaved?'':sx.willSave;d.classList.remove('hidden');await refreshExistingShares()}
async function createPrivateShareLink(){const sx=shareT(shareStoryLanguage()),senderName=$('shareSenderName')?.value.trim(),status=$('shareStatus');if(!senderName){status.textContent=sx.senderRequired;return null}status.textContent=sx.preparing;const storyId=await ensureCurrentBookSaved();localStorage.setItem('moonbeamShareSenderName',senderName);const data=await shareApi('/api/share?action=link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({storyId,senderName})});status.textContent='';await refreshExistingShares();return data.link}
async function shareStoryByLink(method){const sx=shareT(shareStoryLanguage()),status=$('shareStatus');try{const link=await createPrivateShareLink();if(!link)return;if(method==='whatsapp'){const text=(sx.whatsappText||((n,u)=>`${n} sent you a Moonbeam Story ✨\n\n${u}`))($('shareSenderName').value.trim(),link);window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener')}else{await navigator.clipboard.writeText(link);status.textContent=sx.linkCopied||'✓ Link copied'}}catch(e){status.textContent=e.message||String(e)}}
async function ensureCurrentBookSaved(){if(currentBook?.isSaved&&currentBook.savedStoryId)return currentBook.savedStoryId;const id=await saveCurrentStory();if(!id||!currentBook?.savedStoryId)throw new Error(shareT(shareStoryLanguage()).mustSave);return currentBook.savedStoryId}
async function shareApi(path,options={}){const sx=shareT(shareStoryLanguage()),token=await currentAccessToken();if(!token)throw new Error(sx.signInAgain);const headers={...(options.headers||{}),Authorization:`Bearer ${token}`};const r=await fetch(path,{...options,headers});const raw=await r.text();let data={};try{data=JSON.parse(raw)}catch{}if(!r.ok)throw new Error(data?.error||sx.sharingFailed(r.status));return data}
async function sendStoryShares(){const sx=shareT(shareStoryLanguage()),button=document.querySelector('.share-send'),status=$('shareStatus'),senderName=$('shareSenderName')?.value.trim(),recipients=[...document.querySelectorAll('.share-recipient')].map(r=>({email:r.querySelector('.share-recipient-email').value.trim()})).filter(x=>x.email);if(!senderName){status.textContent=sx.senderRequired;return}if(!recipients.length){status.textContent=sx.recipientRequired;return}button.disabled=true;status.textContent=sx.preparing;try{const storyId=await ensureCurrentBookSaved();localStorage.setItem('moonbeamShareSenderName',senderName);const data=await shareApi('/api/share?action=owner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({storyId,senderName,recipients})});status.textContent=sx.sent(data.sent?.length||0,data.failed?.length||0);await refreshExistingShares()}catch(e){status.textContent=e.message||String(e)}finally{button.disabled=false}}
async function refreshExistingShares(){const sx=shareT(shareStoryLanguage()),box=$('existingShares');if(!box)return;if(!currentBook?.savedStoryId){box.innerHTML='';return}try{const data=await shareApi(`/api/share?action=owner&storyId=${encodeURIComponent(currentBook.savedStoryId)}`);if(!data.shares?.length){box.innerHTML='';return}box.innerHTML=`<h3>${escapeHtml(sx.sharedWith)}</h3>${data.shares.map(x=>`<div class="existing-share"><span><b>${escapeHtml(x.recipient_email||sx.privateLink||'Private link')}</b><small>${x.opened_at?escapeHtml(sx.opened):''}${x.opened_at&&x.revoked_at?' · ':''}${x.revoked_at?escapeHtml(sx.revoked):''}</small></span>${x.revoked_at?'':`<button class="secondary" type="button" data-revoke-share="${escapeHtml(x.id)}">${escapeHtml(sx.revoke)}</button>`}</div>`).join('')}`;box.querySelectorAll('[data-revoke-share]').forEach(b=>b.onclick=async()=>{if(!confirm(sx.revokeConfirm))return;try{await shareApi('/api/share?action=owner',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.revokeShare})});await refreshExistingShares()}catch(e){alert(e.message)}})}catch(e){box.innerHTML=`<small>${escapeHtml(e.message)}</small>`}}

const narrationCache=new Map();
let narrationAudio=null,narrationRun=0,narrationTimer=null,narrationStartTimeout=null;
const activeNarrationAudios=new Set();
function splitNarrationSentences(text){const m=String(text||'').match(/[^.!?…]+(?:[.!?…]+[”’\"']?|$)/g);return (m&&m.length?m:[String(text||'')]).map(x=>x.trim()).filter(Boolean)}
function renderNarrationText(text){return splitNarrationSentences(text).map((sentence,i)=>`<span class="narration-sentence" data-sentence="${i}">${escapeHtml(sentence)}</span>`).join(' ')}
function currentPageText(){if(!currentBook)return'';const i=currentBook.currentPage,closingIndex=currentBook.pages.length+1;if(i===0)return currentBook.opening||'';if(i===closingIndex)return currentBook.closing||'';if(i>closingIndex)return'';return currentBook.pages[i-1]?.text||''}
function narrationLanguage(book=currentBook){return book?.child?.language||language}
function narrationKey(){return currentBook?`${currentBook.cacheId}:audio:${narrationLanguage()}:${currentBook.currentPage}`:''}
// V118 — saved books regenerate narration audio on demand through the same TTS response path as live books.
// Story text and illustrations remain the already-saved assets; only /api/narrate is called.
async function getNarration(text,key,pageIndex=currentBook?.currentPage){
 if(narrationCache.has(key))return narrationCache.get(key);
 const book=currentBook,lang=narrationLanguage(book);
 const payload={text,language:lang};let headers={'Content-Type':'application/json'};
 if(book?.isShared)payload.shareToken=book.shareToken;else{const {data:{session}}=await supabaseClient.auth.getSession(),accessToken=session?.access_token;if(!accessToken)throw new Error(uiStatus135().narrationSignIn);headers.Authorization=`Bearer ${accessToken}`;if(book?.isSaved)payload.savedStoryId=book.savedStoryId;else payload.generationRunId=book?.generationRunId||null}
 const r=await fetch('/api/narrate',{method:'POST',headers,body:JSON.stringify(payload)});
 const raw=await r.text();let data={};try{data=JSON.parse(raw)}catch{}if(!r.ok||!data.audio)throw new Error(data?.error||`Narration failed (${r.status})`);
 narrationCache.set(key,data.audio);return data.audio
}
function clearNarrationHighlight(){narrationScrollSentence=-1;document.querySelectorAll('.narration-sentence').forEach(x=>x.classList.remove('speaking'))}
function stopNarration(){narrationRun++;if(narrationStartTimeout){clearTimeout(narrationStartTimeout);narrationStartTimeout=null}if(narrationTimer){clearInterval(narrationTimer);narrationTimer=null}const audios=new Set(activeNarrationAudios);if(narrationAudio)audios.add(narrationAudio);for(const audio of audios){try{audio.onended=null;audio.ontimeupdate=null;audio.pause();audio.currentTime=0;audio.removeAttribute?.('src');audio.load?.()}catch{}}activeNarrationAudios.clear();narrationAudio=null;clearNarrationHighlight();const b=$('narrationControl');if(b){b.textContent='▶';b.classList.remove('loading')}}
function scheduleNarration(delay=120){if(narrationStartTimeout)clearTimeout(narrationStartTimeout);narrationStartTimeout=setTimeout(()=>{narrationStartTimeout=null;startNarrationForCurrentPage()},delay)}
let narrationScrollSentence=-1;
function keepNarratedSentenceVisible(span,idx){
 if(!isPhonePortrait()||!span||idx===narrationScrollSentence)return;
 narrationScrollSentence=idx;
 const content=span.closest('.page-content');
 if(!content)return;
 const cr=content.getBoundingClientRect(),sr=span.getBoundingClientRect();
 // Keep the spoken sentence in the comfortable middle band of the lower text pane.
 // Only the text viewport scrolls; the fixed 60% illustration and navigation never move.
 const upper=cr.top+Math.min(34,cr.height*.16),lower=cr.bottom-Math.min(46,cr.height*.22);
 if(sr.top<upper||sr.bottom>lower){
   const desired=content.scrollTop+(sr.top-cr.top)-(cr.height*.32);
   const max=Math.max(0,content.scrollHeight-content.clientHeight);
   content.scrollTo({top:Math.max(0,Math.min(max,desired)),behavior:'smooth'});
 }
}
function updateNarrationHighlight(audio){const spans=[...document.querySelectorAll('.narration-sentence')];if(!spans.length||!isFinite(audio.duration)||audio.duration<=0)return;const weights=spans.map(s=>Math.max(1,s.textContent.trim().length)),total=weights.reduce((a,b)=>a+b,0);let target=(audio.currentTime/audio.duration)*total,acc=0,idx=0;for(let i=0;i<weights.length;i++){acc+=weights[i];if(target<=acc){idx=i;break}}spans.forEach((s,i)=>s.classList.toggle('speaking',i===idx));keepNarratedSentenceVisible(spans[idx],idx)}
async function startNarrationForCurrentPage(){if(!currentBook||currentBook.currentPage<0)return;for(const a of activeNarrationAudios){try{a.pause();a.currentTime=0}catch{}}activeNarrationAudios.clear();narrationAudio=null;const pageAtStart=currentBook.currentPage,run=++narrationRun,text=currentPageText(),key=narrationKey(),button=$('narrationControl');if(button){button.textContent='…';button.classList.add('loading')}try{const src=await getNarration(text,key);if(run!==narrationRun||!currentBook||currentBook.currentPage!==pageAtStart)return;const audio=new Audio(src);activeNarrationAudios.add(audio);narrationAudio=audio;if(button){button.textContent='⏸';button.classList.remove('loading')}audio.ontimeupdate=()=>{if(currentBook?.currentPage===pageAtStart)updateNarrationHighlight(audio)};audio.onended=()=>{activeNarrationAudios.delete(audio);if(run!==narrationRun||!currentBook||currentBook.currentPage!==pageAtStart)return;clearNarrationHighlight();if(narrationAudio===audio)narrationAudio=null;if(button)button.textContent='▶';if(currentBook.readingMode==='narrated'&&pageAtStart<=currentBook.pages.length+1){narrationStartTimeout=setTimeout(()=>{narrationStartTimeout=null;goNextBookPage(true)},500)}};await audio.play()}catch(e){console.error(e);const message=e?.message||t().narrationUnavailable;if(button){button.textContent='▶';button.classList.remove('loading');button.title=message}if(currentBook?.isSaved)alert(message)} }
function toggleNarration(){if(!currentBook)return;if(narrationAudio&&!narrationAudio.paused){narrationAudio.pause();const b=$('narrationControl');if(b)b.textContent='▶';return}if(narrationAudio&&narrationAudio.paused){narrationAudio.play();const b=$('narrationControl');if(b)b.textContent='⏸';return}startNarrationForCurrentPage()}
function renderBookPage(index){
 stopNarration();
 const book=currentBook,total=book.pages.length+3,clamped=Math.max(0,Math.min(index,total-1));book.currentPage=clamped;if(!isPhonePortrait())book.mobileSide='text';
 const closingIndex=total-2,isOpening=clamped===0,isClosing=clamped===closingIndex,isEnd=clamped===total-1;
 const prev=$('prevPage'),next=$('nextPage'),indicator=$('pageIndicator'),bookEl=$('book');
 if(isEnd){
   const saveButton=`<button class="secondary end-save" id="endSave" type="button" ${book.isSaved?'disabled':''}>${escapeHtml(book.isSaved?(t().storySaved||t().savedBtn):t().save)}</button>`;
   const ownerActions=`${saveButton}<button class="primary end-share-story" id="endShareStory" type="button">${escapeHtml(t().shareStory)}</button><button class="secondary end-new-story" id="endNewStory" type="button">${escapeHtml(t().newStory)}</button>`;
   const sx=shareT(book.child?.language||language),sharedActions=`<div class="shared-conversion"><h3>${escapeHtml(sx.loved)}</h3><p>${escapeHtml(sx.free)}</p><a class="primary shared-create" id="sharedCreateStory" href="/?lang=${encodeURIComponent(book.child?.language||language)}&fromShare=1">${escapeHtml(sx.create)}</a></div>`;
   bookEl.innerHTML=`<div class="paper end-page"><div class="end-page-inner"><div class="end-stars" aria-hidden="true">✦ ☾ ✧</div><div class="end-title">${escapeHtml(t().end)}</div><div class="end-flourish" aria-hidden="true">❦</div>${book.isShared?sharedActions:`<div class="end-actions">${ownerActions}</div>`}</div></div>`;
   if(prev){prev.disabled=false;prev.textContent=t().previous}if(next){next.disabled=true;next.textContent=t().end}if(indicator)indicator.textContent=`${clamped+1} / ${total}`;
   const es=$('endSave');if(es)es.onclick=saveCurrentStory;const sh=$('endShareStory');if(sh)sh.onclick=openShareStory;const en=$('endNewStory');if(en)en.onclick=()=>startNewStory();const sc=$('sharedCreateStory');if(sc)sc.onclick=e=>{e.preventDefault();const nextLanguage=book.child?.language||language||'en-GB';stopNarration();document.body.classList.remove('shared-story-mode','story-mode','desktop-story-mode');location.assign(`/?lang=${encodeURIComponent(nextLanguage)}&fromShare=1`)};
   applyMobileSide();return;
 }
 let text='',label='';if(isOpening){text=book.opening;label=t().beginning}else if(isClosing){text=book.closing;label=''}else{const p=book.pages[clamped-1]||{};text=p.text||'';label=`${t().page} ${clamped}`};
 const wc=String(text).trim().split(/\s+/).filter(Boolean).length;const fitClass=wc>135?' compact-text':wc<85?' roomy-text':'';
 bookEl.innerHTML=`<div class="paper left-page"><div class="page-number">${isOpening?'☾':clamped}</div><div class="page-content">${label?`<div class="chapter-label">${escapeHtml(label)}</div>`:''}<div class="story-text${fitClass}">${renderNarrationText(text)}</div></div><div class="mobile-scroll-cue" aria-hidden="true"><span></span><span></span></div></div><div class="paper right-page"><div class="page-number">${isClosing?'☾':(clamped+1)}</div><div class="illustration-frame"><div class="illustration-loading"><div class="spinner"></div><p>${escapeHtml(t().painting)}</p><small>${escapeHtml(t().paintingSmall)}</small></div></div>${book.readingMode==='narrated'?'<button class="narration-control" id="narrationControl" type="button" aria-label="Play narration">▶</button>':''}</div><button class="mobile-turn-zone mobile-turn-left" aria-label="Previous page" type="button"></button><button class="mobile-turn-zone mobile-turn-right" aria-label="Next page" type="button"></button>`;
 if(prev){prev.disabled=false;prev.textContent=isOpening?coverT().cover:t().previous}if(next){next.disabled=false;next.textContent=t().turn}if(indicator)indicator.textContent=`${clamped+1} / ${total}`;
 const nc=$('narrationControl');if(nc){nc.onclick=e=>{e.stopPropagation();toggleNarration()};nc.textContent=book.readingMode==='narrated'?'⏸':'▶'};
 applyMobileSide();setupMobileScrollCue();requestAnimationFrame(fitDesktopStoryText);loadIllustration(clamped,getIllustrationPrompt(clamped),false);prefetchIllustrations(clamped,1);
 if(book.readingMode==='narrated'&&clamped<closingIndex){const nextText=clamped+1===closingIndex?book.closing:(book.pages[clamped]?.text||'');if(nextText)getNarration(nextText,`${book.cacheId}:audio:${narrationLanguage(book)}:${clamped+1}`,clamped+1).catch(()=>{})}
}
