// V86 — simplified creation flow. One explicit screen at a time on desktop and mobile.
let setupPageIndex=0;
function setupPages(){return [...document.querySelectorAll('#setupTrack .setup-page')]}
const SETUP_NAV_WORDS={
 'en-GB':{back:'Back',home:'Home',story:'Story →'},'en-US':{back:'Back',home:'Home',story:'Story →'},
 'es-ES':{back:'Atrás',home:'Inicio',story:'Historia →'},'es-419':{back:'Atrás',home:'Inicio',story:'Historia →'},
 'fr-FR':{back:'Retour',home:'Accueil',story:'Histoire →'},'de-DE':{back:'Zurück',home:'Startseite',story:'Geschichte →'},
 'it-IT':{back:'Indietro',home:'Inizio',story:'Storia →'},'pt-BR':{back:'Voltar',home:'Início',story:'História →'},
 'pl-PL':{back:'Wstecz',home:'Strona główna',story:'Historia →'}
};
function setupNavWords(){return SETUP_NAV_WORDS[language]||SETUP_NAV_WORDS['en-GB']}
function ensureSetupCardNav(){
 const pages=setupPages(),words=setupNavWords();
 pages.forEach((page,i)=>{
   let nav=page.querySelector('.setup-card-nav');
   if(!nav){nav=document.createElement('div');nav.className='setup-card-nav';page.appendChild(nav)}
   const step=page.dataset.step;
   if(step==='Account'){
     nav.innerHTML=`<button class="secondary setup-home" type="button">← ${words.home}</button>`;
   }else if(step==='Child'){
     nav.innerHTML=`<button class="secondary setup-home" type="button">← ${words.home}</button><button class="primary setup-card-enter" type="button">${words.story}</button>`;
   }else if(step==='Story'){
     nav.innerHTML=`<button class="secondary setup-card-back" type="button">← ${words.back}</button>`;
   }
 })
}
function updateSetupNav(){ensureSetupCardNav();const dots=$('setupDots');if(dots)dots.innerHTML=''}
// V119 — setup cue belongs to the actual setup-page scroll container.
// Its position is derived only from that page's own scroll state; no viewport geometry.
function ensureSetupScrollCues(){
 setupPages().forEach(page=>{
   let cue=page.querySelector(':scope > .setup-scroll-cue');
   if(!cue){cue=document.createElement('div');cue.className='setup-scroll-cue';cue.setAttribute('aria-hidden','true');cue.innerHTML='<span></span><span></span>';page.appendChild(cue)}
 });
}
function updateSetupScrollCue(){
 ensureSetupScrollCues();
 const mobile=window.matchMedia('(max-width:700px)').matches;
 setupPages().forEach((page,i)=>{
   const cue=page.querySelector(':scope > .setup-scroll-cue');if(!cue)return;
   const active=i===setupPageIndex&&page.classList.contains('setup-current');
   const remaining=page.scrollHeight-page.scrollTop-page.clientHeight;
   const moreBelow=!!(mobile&&active&&remaining>6);
   cue.classList.toggle('visible',moreBelow);
   cue.setAttribute('aria-hidden',moreBelow?'false':'true');
   if(moreBelow){
     const top=Math.max(8,page.scrollTop+page.clientHeight-cue.offsetHeight-10);
     cue.style.top=top+'px';
   }
 });
}
function bindSetupScrollCue(){
 ensureSetupScrollCues();
 setupPages().forEach(page=>{if(page.dataset.scrollCueBound)return;page.dataset.scrollCueBound='1';page.addEventListener('scroll',updateSetupScrollCue,{passive:true})});
 if(!window.__moonbeamSetupCueBound){window.__moonbeamSetupCueBound=true;window.addEventListener('resize',updateSetupScrollCue,{passive:true})}
 requestAnimationFrame(()=>requestAnimationFrame(updateSetupScrollCue));
}
function goSetupPage(index,instant=false){
 const track=$('setupTrack'),pages=setupPages();if(!track||!pages.length)return;
 let requested=Math.max(0,Math.min(Number(index)||0,pages.length-1));
 // Authentication is a hard gate. Account -> Child occurs only after a real session exists.
 if(!currentUser&&requested>0){requested=0;const status=$('authStatus');if(status)status.textContent=uiStatus135().continueSignIn}
 setupPageIndex=requested;
 pages.forEach((page,i)=>{const active=i===setupPageIndex;page.classList.toggle('setup-current',active);page.setAttribute('aria-hidden',active?'false':'true')});
 track.scrollLeft=0;track.scrollTop=0;
 const storyIndex=pages.findIndex(p=>p.dataset.step==='Story');
 if(setupPageIndex===storyIndex&&currentUser)refreshStoryCreditConsentUI().catch(()=>{});
 updateSetupNav();
 bindSetupScrollCue();
}
function initSetupDeck(){
 const track=$('setupTrack');if(!track)return;
 track.addEventListener('click',e=>{
   if(e.target.closest('.setup-home')){showMoonbeamLanding();return}
   if(e.target.closest('.setup-card-back')){goSetupPage(Math.max(0,setupPageIndex-1),true);return}
   if(e.target.closest('.setup-card-enter')){
     if(!currentUser){setAuthStatus(uiStatus135().continueSignIn,true);goSetupPage(0,true);return}
     goSetupPage(Math.min(setupPages().length-1,setupPageIndex+1),true);return
   }
 });
 updateSetupNav();goSetupPage(setupPageIndex,true);
}
initSetupDeck();
$('appCreateNav')?.addEventListener('click',()=>{const pages=setupPages(),i=pages.findIndex(p=>p.dataset.step==='Child');goSetupPage(i>=0?i:1,true)});
$('appSavedNav')?.addEventListener('click',()=>{const pages=setupPages(),i=pages.findIndex(p=>p.dataset.step==='Story');goSetupPage(i>=0?i:pages.length-1,true);requestAnimationFrame(()=>document.querySelector('.story-library-inline')?.scrollIntoView({block:'nearest'}))});
// V142 — mobile application header mirrors the proven V141 desktop routes.
